  renderTab('chat');
  const mg=$('#manageGroup');if(mg)mg.onclick=()=>manageGroup(d);
  const tg=$('#toggleGroup');if(tg)tg.onclick=async()=>{try{await api('/api/groups/'+id+'/status',{method:'PATCH',body:JSON.stringify({closed:!d.group.closed})});drawGroup(id);toast(d.group.closed?'Gruppe geöffnet':'Gruppe geschlossen')}catch(e){toast(e.message)}};
  const dg=$('#deleteGroup');if(dg)dg.onclick=async()=>{if(confirm('Gruppe wirklich löschen?')){await api('/api/groups/'+id,{method:'DELETE'});selectedGroup=null;chatView();toast('Gruppe gelöscht')}};
