async function groups(){const a=$('#app');a.innerHTML='<div class="loading">Gruppen werden geladen …</div>';try{const d=await api('/api/groups');a.innerHTML=`<div class="section-head"><div><h2>👥 Meine Gruppen</h2><div class="muted">Nur Gruppenmitglieder sehen private Gruppen. Besitzer können Gruppen schließen und Mitglieder verwalten.</div></div><button class="primary" id="groupsNew">＋ Gruppe erstellen</button></div><div class="scroll-frame both groups-scroll"><div class="group-grid">${d.groups.length?d.groups.map(g=>`<div class="card group-card"><div class="mini-avatar">${initials(g.name)}</div><h3>${esc(g.name)}</h3><div class="muted">${g.memberCount} Mitglieder · Besitzer: ${esc(g.ownerName)}</div><div class="members">${(g.members||[]).slice(0,6).map(m=>`<div class="mini-avatar" title="${esc(m.name)}">${initials(m.name)}</div>`).join('')}</div><div class="muted">${g.closed?'🔒 Geschlossen':'🟢 Offen'}</div><button class="secondary full" data-open-group="${g.id}">💬 Gruppe öffnen</button></div>`).join(''):'<div class="card"><div class="muted">Du bist noch in keiner Gruppe.</div></div>'}</div></div>`;document.querySelectorAll('[data-open-group]').forEach(b=>b.onclick=()=>{selectedGroup=Number(b.dataset.openGroup);chatMode='group';setView('chat');setTimeout(()=>openGroup(selectedGroup),0)});$('#groupsNew').onclick=async()=>{const name=prompt('Name der neuen Gruppe:');if(!name?.trim())return;const users=(await api('/api/groups/users')).users;const selected=prompt('Mitglieder hinzufügen (Namen mit Komma trennen):\n\n'+users.map(u=>u.name).join('\n'));const names=(selected||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);const ids=users.filter(u=>names.includes(u.name.toLowerCase())).map(u=>u.id);try{await api('/api/groups',{method:'POST',body:JSON.stringify({name:name.trim(),memberIds:ids})});groups();toast('Gruppe erstellt')}catch(e){toast(e.message)}}}catch(e){a.innerHTML=`<div class="card">${esc(e.message)}</div>`}}
async function groupUpload(id){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="dialog-card"><div class="dialog-head"><h3>Datei für die Gruppe</h3><button type="button" class="icon-btn" id="x">×</button></div><input class="input" type="file" id="gf" required><label id="gcodeLabel" hidden>🔑 Admin-Freigabecode<input class="input" id="gcode" placeholder="Code vom Admin"></label><div id="ginfo" class="muted">Bis 10 MB ohne Code, über 10 MB mit Admin-Freigabe.</div><button class="primary">Hochladen</button><div id="ge" class="auth-error"></div></form>`;document.body.append(d);d.showModal();$('#x').onclick=()=>d.remove();$('#gf').onchange=()=>{const f=$('#gf').files[0],big=f&&f.size>10*1024*1024;$('#gcodeLabel').hidden=!big||currentUser.role==='admin';$('#ginfo').textContent=big?(currentUser.role==='admin'?'Über 10 MB: Admin benötigt keinen Code.':'Über 10 MB: Admin-Freigabecode erforderlich.'):'Bis 10 MB ohne Code.'};d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=$('#gf').files[0];if(!f)return;if(f.size>50*1024*1024)return $('#ge').textContent='Maximal 50 MB.';const r=new FileReader();r.onload=async()=>{try{await api(`/api/groups/${id}/files`,{method:'POST',body:JSON.stringify({name:f.name,mime:f.type,data:r.result,approvalCode:$('#gcode').value.trim()})});d.close();d.remove();drawGroup(id);toast('Datei geteilt')}catch(x){$('#ge').textContent=x.message}};r.readAsDataURL(f)}}

function groupEventDialog(id){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="dialog-card"><div class="dialog-head"><h3>Gemeinsamer Termin</h3><button type="button" class="icon-btn" id="x">×</button></div><input class="input" name="title" placeholder="Titel" required><div class="form-row"><input class="input" name="date" type="date" required><input class="input" name="time" type="time" required></div><textarea class="input" name="description" rows="3" placeholder="Beschreibung"></textarea><button class="primary">Speichern</button></form>`;document.body.append(d);d.showModal();$('#x').onclick=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api(`/api/groups/${id}/events`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});d.close();d.remove();drawGroup(id);toast('Termin gespeichert')}catch(x){toast(x.message)}}}
async function manageGroup(d){const users=(await api('/api/groups/users')).users;const current=new Set(d.members.map(m=>m.id));const available=users.filter(u=>!current.has(u.id));const name=prompt('Neuer Gruppenname:',d.group.name);if(name===null)return;const addNames=available.length?prompt('Neue Mitglieder hinzufügen (Namen mit Komma trennen):\n\n'+available.map(u=>u.name).join('\n')):'';const removeNames=d.members.filter(m=>m.id!==d.group.ownerId).length?prompt('Mitglieder entfernen (Namen mit Komma trennen):\n\n'+d.members.filter(m=>m.id!==d.group.ownerId).map(u=>u.name).join('\n')):'';const addIds=(addNames||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean).map(n=>available.find(u=>u.name.toLowerCase()===n)?.id).filter(Boolean);const removeIds=(removeNames||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean).map(n=>d.members.find(u=>u.name.toLowerCase()===n)?.id).filter(Boolean);let adminIds;const canManageAdmins=d.group.ownerId===currentUser.id||currentUser.role==='admin';if(canManageAdmins){const admins=prompt('Gruppen-Admins festlegen (Namen mit Komma trennen):\n\n'+d.members.filter(m=>m.id!==d.group.ownerId).map(u=>u.name).join('\n'),d.members.filter(m=>m.groupRole==='admin').map(u=>u.name).join(', '));if(admins!==null)adminIds=(admins||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean).map(n=>d.members.find(u=>u.name.toLowerCase()===n)?.id).filter(Boolean)}try{await api('/api/groups/'+d.group.id+'/settings',{method:'PATCH',body:JSON.stringify({name,addMemberIds:addIds,removeMemberIds:removeIds,adminMemberIds:adminIds})});await drawGroup(d.group.id);toast('Gruppe aktualisiert')}catch(e){toast(e.message)}}

async function cloud(){const a=$('#app');a.innerHTML='<div class="loading">Cloud wird geladen …</div>';try{const d=await api('/api/cloud');a.innerHTML=`<div class="section-head"><div><h2>☁ Cloud</h2><div class="muted">Private Dateien und Dateien für deine gesamte Klasse.</div></div><button class="primary" id="uploadFile">＋ Datei hochladen</button></div><div class="card cloud-info"><b>🔒 Privat</b><span class="muted">Nur du kannst die Datei sehen.</span><b>👥 Klasse</b><span class="muted">Alle Mitglieder der ausgewählten Klasse können sie sehen und herunterladen.</span></div><div class="scroll-frame both cloud-scroll"><div class="file-grid">${d.files.length?d.files.map(f=>`<div class="file-card"><div class="file-icon">${fileIcon(f.mime)}</div><h3 title="${esc(f.name)}">${esc(f.name)}</h3><div class="muted">${formatBytes(f.size)} · ${f.scope==='class'?'👥 '+esc(d.classes.find(c=>c.id===f.classId)?.name||'Klasse'):'🔒 Privat'}</div><div class="muted">von ${esc(f.ownerName)}</div><div class="file-actions"><button class="secondary" data-download-file="${f.id}">⬇ Herunterladen</button>${f.ownerId===currentUser.id||currentUser.role==='admin'?`<button class="danger" data-delete-file="${f.id}">Löschen</button>`:''}</div></div>`).join(''):'<div class="card"><div class="muted">Noch keine Dateien vorhanden.</div></div>'}</div></div>`;$('#uploadFile').onclick=()=>openUploadDialog(d.classes);document.querySelectorAll('[data-download-file]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/cloud/'+b.dataset.downloadFile+'/download');window.location=d.url}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-file]').forEach(b=>b.onclick=async()=>{if(!confirm('Datei wirklich löschen?'))return;try{await api('/api/cloud/'+b.dataset.deleteFile,{method:'DELETE'});cloud();toast('Datei gelöscht')}catch(e){toast(e.message)}})}catch(e){a.innerHTML=`<div class="card">${esc(e.message)}</div>`}}
function fileIcon(mime){if((mime||'').includes('pdf'))return'📕';if((mime||'').startsWith('image/'))return'🖼️';if((mime||'').includes('word'))return'📝';if((mime||'').includes('sheet')||(mime||'').includes('excel'))return'📊';if((mime||'').includes('presentation')||(mime||'').includes('powerpoint'))return'📽️';return'📄'}
function formatBytes(n){if(n<1024)return n+' B';if(n<1024*1024)return(n/1024).toFixed(0)+' KB';if(n<1024*1024*1024)return(n/1024/1024).toFixed(1)+' MB';return(n/1024/1024/1024).toFixed(2)+' GB'}
function openUploadDialog(classes){const old=$('#uploadDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='uploadDialog';d.className='dialog';d.innerHTML=`<form class="dialog-card" id="uploadForm"><div class="dialog-head"><h3>Datei teilen</h3><button type="button" class="icon-btn" id="closeUpload">×</button></div><label>Datei<input id="uploadInput" class="input" type="file" required></label><label>Freigabe<select id="uploadScope" class="input"><option value="private">🔒 Nur für mich</option><option value="class">👥 Für die gesamte Klasse</option></select></label><label id="uploadClassLabel">Klasse<select id="uploadClass" class="input">${classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label id="approvalLabel" hidden>🔑 Admin-Freigabecode<input id="approvalCode" class="input" placeholder="Code vom Admin" autocomplete="off"></label><div id="uploadHint" class="muted">Bis 10 MB ohne Code. Über 10 MB: Admin-Freigabecode erforderlich.</div><div id="uploadProgressWrap" hidden><div class="muted" id="uploadProgressText">Upload wird vorbereitet …</div><progress id="uploadProgress" value="0" max="100" style="width:100%"></progress></div><button class="primary" id="uploadSubmit">Hochladen & teilen</button><div id="uploadError" class="auth-error"></div></form>`;document.body.append(d);d.showModal();const input=$('#uploadInput');const refreshLimit=()=>{const f=input.files[0],big=f&&f.size>10*1024*1024;$('#approvalLabel').hidden=!big||currentUser.role==='admin';$('#uploadHint').textContent=big?(currentUser.role==='admin'?'Datei über 10 MB: Du bist Admin und brauchst keinen Code.':'Datei über 10 MB: Bitte einen Admin-Freigabecode eingeben.'):'Bis 10 MB ohne Code. Über 10 MB: Admin-Freigabecode erforderlich.'};input.onchange=refreshLimit;$('#uploadScope').onchange=()=>$('#uploadClassLabel').style.display=$('#uploadScope').value==='class'?'grid':'none';$('#uploadScope').dispatchEvent(new Event('change'));$('#closeUpload').onclick=()=>d.close();$('#uploadForm').onsubmit=async e=>{e.preventDefault();const file=input.files[0];if(!file)return;if(file.size>50*1024*1024){$('#uploadError').textContent='Maximal 50 MB pro Datei.';return}const reader=new FileReader();reader.onload=()=>{const payload=JSON.stringify({name:file.name,mime:file.type,data:reader.result,scope:$('#uploadScope').value,classId:Number($('#uploadClass').value||0),approvalCode:$('#approvalCode').value.trim()});$('#uploadProgressWrap').hidden=false;$('#uploadSubmit').disabled=true;const xhr=new XMLHttpRequest();xhr.open('POST','/api/cloud');xhr.setRequestHeader('Content-Type','application/json');xhr.upload.onprogress=e=>{if(e.lengthComputable){const pct=Math.round(e.loaded/e.total*100);$('#uploadProgress').value=pct;$('#uploadProgressText').textContent='Upload läuft … '+pct+'%'}};xhr.onload=()=>{let x={};try{x=JSON.parse(xhr.responseText)}catch{};if(xhr.status>=200&&xhr.status<300){d.close();d.remove();cloud();toast('Datei erfolgreich geteilt')}else{$('#uploadError').textContent=x.error||'Upload fehlgeschlagen.';$('#uploadSubmit').disabled=false}};xhr.onerror=()=>{$('#uploadError').textContent='Die Verbindung zum Server ist fehlgeschlagen.';$('#uploadSubmit').disabled=false};xhr.send(payload)};reader.onerror=()=>{$('#uploadError').textContent='Datei konnte nicht gelesen werden.'};reader.readAsDataURL(file)}}

async function calendar(){const a=$('#app');a.innerHTML='<div class="loading">Kalender wird geladen …</div>';try{const d=await api('/api/calendar');const selected=d.classes[0];const now=new Date();const y=now.getFullYear(),m=now.getMonth();const monthLabel=new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(now);const counts={homework:d.events.filter(e=>e.type==='homework').length,appointment:d.events.filter(e=>e.type==='appointment').length,exam:d.events.filter(e=>e.type==='exam').length};a.innerHTML=`<div class="section-head"><div><h2>📅 Klassenkalender</h2><div class="muted">Nur Mitglieder deiner Klasse sehen diese Termine.</div></div><button class="primary" id="newCalendarItem">＋ Eintrag hinzufügen</button></div><div class="calendar-stats"><div class="card"><b>📚 ${counts.homework}</b><span>Hausaufgaben</span></div><div class="card"><b>📌 ${counts.appointment}</b><span>Termine</span></div><div class="card"><b>📝 ${counts.exam}</b><span>Prüfungen</span></div></div><div class="card calendar-card"><div class="calendar-toolbar"><div><h2>${monthLabel}</h2><span class="muted">${d.classes.map(c=>esc(c.name)).join(' · ')}</span></div></div><div class="scroll-frame x calendar-scroll"><div class="calendar-grid">${calendarCells(y,m,d.events)}</div></div></div><div class="section-head"><h2>Einträge</h2></div><div class="event-list">${d.events.length?d.events.map(e=>`<div class="card event-row"><div class="event-type ${e.type}">${eventIcon(e.type)}</div><div class="grow"><b>${esc(e.title)}</b><div class="muted">${eventTypeName(e.type)} · ${e.date} · ${e.time}${e.subject?' · '+esc(e.subject):''}</div>${e.description?`<div class="muted">${esc(e.description)}</div>`:''}<small class="muted">${esc(e.className)} · eingetragen von ${esc(e.creatorName)}</small></div>${e.creatorId===currentUser.id||currentUser.role==='admin'?`<button class="danger" data-delete-event="${e.id}">Löschen</button>`:''}</div>`).join(''):'<div class="card muted">Noch keine Hausaufgaben, Termine oder Prüfungen.</div>'}</div>`;$('#newCalendarItem').onclick=()=>openEventDialog(d.classes);document.querySelectorAll('[data-delete-event]').forEach(b=>b.onclick=async()=>{if(!confirm('Eintrag wirklich löschen?'))return;try{await api('/api/calendar/'+b.dataset.deleteEvent,{method:'DELETE'});calendar();toast('Eintrag gelöscht')}catch(e){toast(e.message)}})}catch(e){a.innerHTML=`<div class="card">${esc(e.message)}</div>`}}
function calendarCells(y,m,events){const names=['Mo','Di','Mi','Do','Fr','Sa','So'];const first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),start=(first.getDay()+6)%7;let out=names.map(n=>`<div class="day day-head">${n}</div>`).join('');for(let i=0;i<start;i++)out+='<div class="day"></div>';for(let day=1;day<=days;day++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,today=iso===new Date().toISOString().slice(0,10);out+=`<div class="day ${today?'today':''}"><div class="day-num">${day}</div>${events.filter(e=>e.date===iso).map(e=>`<div class="event ${e.type}" title="${esc(e.title)}">${eventIcon(e.type)} ${esc(e.title)}</div>`).join('')}</div>`}return out}
function eventTypeName(t){return t==='homework'?'Hausaufgabe':t==='exam'?'Prüfung':'Termin'}function eventIcon(t){return t==='homework'?'📚':t==='exam'?'📝':'📌'}
function openEventDialog(classes){const old=$('#eventDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='eventDialog';d.className='dialog';d.innerHTML=`<form class="dialog-card" id="eventForm"><div class="dialog-head"><h3>Klassenkalender</h3><button type="button" class="icon-btn" id="closeEvent">×</button></div><label>Art<select name="type" class="input"><option value="homework">📚 Hausaufgabe</option><option value="appointment">📌 Termin</option><option value="exam">📝 Prüfung</option></select></label><label>Klasse<select name="classId" class="input">${classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Titel<input name="title" class="input" placeholder="z. B. Mathe S. 84 Nr. 3–6" required></label><div class="form-row"><label>Datum<input name="date" class="input" type="date" required></label><label>Uhrzeit<input name="time" class="input" type="time" required></label></div><label>Fach (optional)<input name="subject" class="input" placeholder="Mathe, Deutsch …"></label><label>Beschreibung (optional)<textarea name="description" class="input" rows="3" placeholder="Weitere Infos …"></textarea><button class="primary">Im Klassenkalender speichern</button><div id="eventError" class="auth-error"></div></form>`;document.body.append(d);d.showModal();$('#closeEvent').onclick=()=>{d.close();d.remove()};$('#eventForm').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/api/calendar',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});d.close();d.remove();calendar();toast('Kalendereintrag gespeichert')}catch(x){$('#eventError').textContent=x.message}}}
async function timetable(){
 const el=$('#app');el.innerHTML='<div class="loading">Stundenplan wird geladen …</div>';
 try{
  const d=await api('/api/timetable'),days=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag'];
  const cls=d.classes[0], rows=(d.timetable||[]).filter(x=>!cls||x.classId===cls.id);
  const toMin=t=>{const [h,m]=String(t||'00:00').split(':').map(Number);return h*60+m};
  el.innerHTML=`<div class="section-head"><div><h2>🕐 Stundenplan</h2><div class="muted">${cls?esc(cls.name):'Keine Klasse'} · Jede Klasse hat ihren eigenen Stundenplan und jede Unterrichtsstunde hat eigene Zeiten.</div></div></div>
  ${cls?`<div class="scroll-frame x timetable-scroll"><div class="timetable-grid">${days.map((day,i)=>{const n=i+1,items=rows.filter(x=>x.day===n).sort((x,y)=>x.period-y.period);return `<div class="timetable-day"><h3>${day}</h3>${items.length?items.map((x,idx)=>{const next=items[idx+1];const gap=next?toMin(next.startTime)-toMin(x.endTime):0;return `<div class="lesson"><span class="lesson-time">${esc(x.startTime||'')}<br><small>${esc(x.endTime||'')}</small></span><div><b>${esc(x.subject)}</b><div class="muted">${esc(x.teacher||'')} · ${esc(x.room||'')}</div><small class="muted">${esc(cls.name)}</small>${gap>0?`<div class="break-note">☕ Pause: ${gap} Min.</div>`:''}</div></div>`}).join(''):'<div class="muted">Kein Unterricht.</div>'}</div>`}).join('')}</div></div>
  <div class="card timetable-info"><b>⏱️ Individuelle Zeiten</b><span>Die Start- und Endzeit wird für jede einzelne Stunde gespeichert. Dadurch können die erste, zweite, dritte usw. Pause unterschiedlich lang sein. Der Stundenplan ist pro Klasse getrennt.</span></div>`:'<div class="card">Du bist noch keiner Klasse zugeordnet.</div>'}`;
 }catch(e){el.innerHTML=`<div class="card">${esc(e.message)}</div>`}
}
function profile(){const av=currentUser.avatarMode==='emoji'&&currentUser.avatarEmoji?currentUser.avatarEmoji:initials(currentUser.name);return `<div class="profile-grid"><div class="card profile-card"><div class="profile-big" style="${currentUser.avatarColor?`background:${esc(currentUser.avatarColor)}`:''}">${esc(av)}</div><h2>${esc(currentUser.name)}</h2><p class="muted">${currentUser.role==='admin'?'Administrator':'Klassenmitglied'}</p><p class="muted">${esc(currentUser.bio||'Noch keine Profilbeschreibung.')}</p></div><div class="card"><div class="section-head"><h2>Profil bearbeiten</h2></div><div class="form-row"><label>Name<input class="input" id="profileName" value="${esc(currentUser.name)}"></label><label>Profilfarbe<input class="input" id="profileColor" type="color" value="${esc(currentUser.avatarColor||'#38bdf8')}"></label></div><div class="form-row"><label>Profilbild-Typ<select class="input" id="avatarMode"><option value="letter" ${currentUser.avatarMode==='letter'?'selected':''}>Buchstabe</option><option value="emoji" ${currentUser.avatarMode==='emoji'?'selected':''}>Emoji / Unicode</option></select></label><label>Emoji oder Zeichen<input class="input" id="avatarEmoji" maxlength="32" value="${esc(currentUser.avatarEmoji||'')}" placeholder="z. B. 🚀, 🐱, ☀️, 𝄞 …"></label></div><div class="muted">Du kannst hier praktisch jedes Unicode-Zeichen bzw. Emoji einfügen, das dein Gerät unterstützt.</div><label>Über dich<textarea class="input" id="profileBio" maxlength="160" rows="3" placeholder="Kurze Profilbeschreibung">${esc(currentUser.bio||'')}</textarea></label><button class="primary" id="saveProfile">💾 Profil speichern</button><div class="section-head"><h2>Design</h2></div><div class="design-presets"><button class="secondary" data-preset="current">Aktuell</button><button class="secondary" data-preset="white">Weiße Version</button><button class="secondary" data-preset="midnight">Midnight</button><button class="secondary" data-preset="ocean">Ocean</button></div><div class="form-row"><label>Akzentfarbe<input class="input" id="designAccent" type="color" value="${esc(state.accent||'#38bdf8')}"></label><label>Hintergrund<input class="input" id="designBg" type="color" value="${esc(state.bg||'#0b1220')}"></label></div><div class="form-row"><label>Panel-Farbe<input class="input" id="designPanel" type="color" value="${esc(state.panel||'#111c2e')}"></label><label>Eckenradius<input class="input" id="designRadius" type="range" min="8" max="30" value="${esc(state.radius)}"></label></div><button class="secondary" id="saveDesignBtn">💾 Eigenes Design speichern</button></div></div>`}
async function adminView(){
 const a=$('#app');a.innerHTML='<div class="loading">Administration wird geladen …</div>';
 try{
  const [s,u,c,l,t,codes]=await Promise.all([api('/api/admin/stats'),api('/api/admin/users'),api('/api/admin/classes'),api('/api/admin/audit'),api('/api/timetable'),api('/api/admin/upload-codes')]);
  const classes=c.classes||[];
  a.innerHTML=`<div class="section-head"><div><h2>🛡️ Administration</h2><div class="muted">Als Admin hast du die volle Verwaltung über Benutzer, Klassen und Stundenpläne.</div></div><div class="row-actions"><button class="primary" id="newClass">＋ Klasse erstellen</button><button class="secondary" id="refreshAdmin">↻ Aktualisieren</button></div></div>
  <div class="grid">
   <div class="card stat"><span>👤</span><div><b>${s.users}</b><small>Benutzer</small></div></div>
   <div class="card stat"><span>👥</span><div><b>${s.classes}</b><small>Klassen</small></div></div>
   <div class="card stat"><span>💬</span><div><b>${s.messages}</b><small>Nachrichten</small></div></div>
   <div class="card stat"><span>🛡</span><div><b>${s.admins}</b><small>Admins</small></div></div>
  </div>
  <div class="card"><div class="section-head"><div><h2>🏫 Klassen verwalten</h2><div class="muted">Klassen umbenennen, Mitglieder verwalten oder komplett löschen.</div></div></div>
   <div class="scroll-frame y admin-scroll">${classes.map(cl=>`<div class="admin-class"><div class="list-row"><div class="mini-avatar">🏫</div><div class="grow"><b>${esc(cl.name)}</b><div class="muted">${cl.members.length} Mitglieder · ID ${cl.id}</div></div><button class="secondary" data-rename-class="${cl.id}">✏️ Umbenennen</button><button class="danger" data-delete-class="${cl.id}">🗑 Klasse löschen</button></div><div class="member-chips">${cl.members.map(m=>`<span class="chip">${esc(m.name)} <button data-remove="${cl.id}:${m.id}">×</button></span>`).join('')}</div><select data-add="${cl.id}"><option value="">＋ Mitglied hinzufügen …</option>${u.users.filter(x=>x.status==='active'&&!cl.members.some(m=>m.id===x.id)).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div>`).join('')||'<div class="muted">Keine Klassen vorhanden.</div>'}</div>
  </div>
  <div class="card"><div class="section-head"><div><h2>🕐 Stundenplan-Editor</h2><div class="muted">Für jeden Tag separat Zeiten einstellen. Mittwoch kann z. B. eine andere Startzeit oder Pause haben.</div></div></div>
   <div class="admin-timetable-toolbar"><label>Klasse<select id="ttClass">${classes.map(cl=>`<option value="${cl.id}">${esc(cl.name)}</option>`).join('')}</select></label><label>Tag<select id="ttDay"><option value="1">Montag</option><option value="2">Dienstag</option><option value="3">Mittwoch</option><option value="4">Donnerstag</option><option value="5">Freitag</option></select></label></div>
   <div id="ttEditor"></div>
  </div>
  <div class="card"><h2>👤 Benutzer & Rechte</h2><div class="scroll-frame y admin-scroll"><div class="admin-users">${u.users.map(x=>`<div class="list-row"><div class="mini-avatar">${initials(x.name)}</div><div class="grow"><b>${esc(x.name)}</b><div class="muted">${x.role} · ${x.status} · ${x.online?'🟢 Online':'⚪ Offline'}</div></div><select data-role="${x.id}"><option value="user" ${x.role==='user'?'selected':''}>User</option><option value="admin" ${x.role==='admin'?'selected':''}>Admin</option></select><select data-status="${x.id}"><option value="active" ${x.status==='active'?'selected':''}>Aktiv</option><option value="banned" ${x.status==='banned'?'selected':''}>Gesperrt</option></select><button class="secondary" data-mod-name="${x.id}">${x.moderation?.nameHidden?'↩️ Name zeigen':'🚫 Name'}</button><button class="secondary" data-mod-bio="${x.id}">${x.moderation?.bioHidden?'↩️ Bio zeigen':'🚫 Bio'}</button><button class="secondary" data-mod-avatar="${x.id}">${x.moderation?.avatarHidden?'↩️ Bild zeigen':'🚫 Bild'}</button><button class="danger" data-del="${x.id}">Löschen</button></div>`).join('')}</div></div></div>
  <div class="card"><div class="section-head"><div><h2>🔑 Cloud-Freigabecodes</h2><div class="muted">Dateien über 10 MB benötigen einen einmaligen Code. Codes sind 30 Minuten gültig.</div></div><button class="primary" id="newUploadCode">＋ Code generieren</button></div><div id="uploadCodes" class="list">${(codes.codes||[]).map(x=>`<div class="list-row"><div class="grow"><b style="font-family:monospace;letter-spacing:1px">${esc(x.code)}</b><div class="muted">gültig bis ${new Date(x.expiresAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</div></div><button class="secondary" data-copy-code="${esc(x.code)}">Kopieren</button></div>`).join('')||'<span class="muted">Keine aktiven Codes.</span>'}</div></div>
  <div class="card"><h2>📜 Audit-Log</h2><div class="scroll-frame y admin-scroll"><div class="list">${l.logs.slice().reverse().map(x=>`<div class="list-row"><div class="grow"><b>${esc(x.action)}</b><div class="muted">${esc(x.detail)}</div></div><small class="muted">${new Date(x.createdAt).toLocaleString('de-DE')}</small></div>`).join('')||'<span class="muted">Noch keine Aktionen.</span>'}</div></div></div>`;
  window._adminTimetable=t;
  bindAdmin();
  renderTimetableEditor();
 }catch(e){a.innerHTML=`<div class="card">${esc(e.message)}</div>`}
}
function renderTimetableEditor(){
 const box=$('#ttEditor');if(!box)return;
 const classes=window._adminTimetable?.classes||[];const cid=Number($('#ttClass')?.value||classes[0]?.id),day=Number($('#ttDay')?.value||1);
 const all=window._adminTimetable?.timetable||[];const rows=all.filter(x=>x.classId===cid&&x.day===day).sort((x,y)=>x.period-y.period);
 box.innerHTML=`<div class="card subtle"><b>💡 Jede Stunde hat eigene Zeiten.</b><div class="muted">Du kannst z. B. 08:00–08:45, danach 09:00–09:45 und danach 10:05–10:50 einstellen. Die Pausen werden automatisch aus den Zeitabständen berechnet.</div></div>
 <div class="table-wrap scroll-frame x"><table class="admin-table"><thead><tr><th>Stunde</th><th>Start</th><th>Ende</th><th>Pause danach</th><th>Fach</th><th>Lehrer</th><th>Raum</th><th></th></tr></thead><tbody>${Array.from({length:Math.max(6,rows.length)},(_,i)=>{const p=i+1,r=rows.find(x=>x.period===p),next=rows.find(x=>x.period===p+1);const gap=r&&next&&r.endTime&&next.startTime?Math.max(0,(Number(next.startTime.slice(0,2))*60+Number(next.startTime.slice(3)))-(Number(r.endTime.slice(0,2))*60+Number(r.endTime.slice(3)))):'';return `<tr><td>${p}</td><td><input class="input tt-start" type="time" data-period="${p}" value="${esc(r?.startTime||'08:00')}"></td><td><input class="input tt-end" type="time" data-period="${p}" value="${esc(r?.endTime||'08:45')}"></td><td>${gap!==''?gap+' Min.':'—'}</td><td><input class="input tt-subject" data-period="${p}" value="${esc(r?.subject||'')}" placeholder="Fach"></td><td><input class="input tt-teacher" data-period="${p}" value="${esc(r?.teacher||'')}" placeholder="Lehrer"></td><td><input class="input tt-room" data-period="${p}" value="${esc(r?.room||'')}" placeholder="Raum"></td><td><button class="primary tt-save" data-period="${p}">${r?'💾':'＋'}</button>${r?` <button class="danger tt-delete" data-id="${r.id}">🗑</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`;
 box.querySelectorAll('.tt-save').forEach(b=>b.onclick=async()=>saveTimetableRow(cid,day,Number(b.dataset.period)));
 box.querySelectorAll('.tt-delete').forEach(b=>b.onclick=async()=>{if(!confirm('Diese Stunde wirklich löschen?'))return;try{await api('/api/admin/timetable/'+b.dataset.id,{method:'DELETE'});toast('Stunde gelöscht');adminView()}catch(e){toast(e.message)}});
}
async function saveTimetableRow(classId,day,period){
 const get=(cls)=>document.querySelector(`.${cls}[data-period="${period}"]`)?.value.trim()||'';
 const body={classId,day,period,startTime:get('tt-start'),endTime:get('tt-end'),subject:get('tt-subject'),teacher:get('tt-teacher'),room:get('tt-room')};
 if(!body.subject)return toast('Bitte ein Fach eintragen.');
 if(!body.startTime||!body.endTime||body.endTime<=body.startTime)return toast('Bitte gültige Start- und Endzeiten eintragen.');
 try{await api('/api/admin/timetable',{method:'POST',body:JSON.stringify(body)});toast('Stunde gespeichert');adminView()}catch(e){toast(e.message)}
}
function bindAdmin(){
 const nc=$('#newClass');if(nc)nc.onclick=async()=>{const name=prompt('Klassenname, z. B. 8A');if(name?.trim())try{await api('/api/admin/classes',{method:'POST',body:JSON.stringify({name:name.trim()})});adminView()}catch(e){toast(e.message)}};
 const ref=$('#refreshAdmin');if(ref)ref.onclick=()=>adminView();
 document.querySelectorAll('[data-rename-class]').forEach(b=>b.onclick=async()=>{const name=prompt('Neuer Klassenname:');if(!name?.trim())return;try{await api('/api/admin/classes/'+b.dataset.renameClass,{method:'PATCH',body:JSON.stringify({name:name.trim()})});toast('Klasse umbenannt');adminView()}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-delete-class]').forEach(b=>b.onclick=async()=>{if(!confirm('ACHTUNG: Klasse, Mitgliederzuordnungen, Klassenchat, Stundenplan, Klassendateien und Klassentermine werden gelöscht. Wirklich fortfahren?'))return;try{await api('/api/admin/classes/'+b.dataset.deleteClass,{method:'DELETE'});toast('Klasse gelöscht');adminView()}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-role]').forEach(s=>s.onchange=async()=>{try{await api('/api/admin/users/'+s.dataset.role,{method:'PATCH',body:JSON.stringify({role:s.value})});toast('Rolle gespeichert')}catch(e){toast(e.message);adminView()}});
 document.querySelectorAll('[data-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/admin/users/'+s.dataset.status,{method:'PATCH',body:JSON.stringify({status:s.value})});toast('Status gespeichert')}catch(e){toast(e.message);adminView()}});
 document.querySelectorAll('[data-mod-name],[data-mod-bio],[data-mod-avatar]').forEach(b=>b.onclick=async()=>{const field=b.dataset.modName?'nameHidden':b.dataset.modBio?'bioHidden':'avatarHidden';try{const users=await api('/api/admin/users');const u=users.users.find(x=>x.id===Number(b.dataset.modName||b.dataset.modBio||b.dataset.modAvatar));await api('/api/admin/users/'+u.id,{method:'PATCH',body:JSON.stringify({[field]:!u.moderation?.[field]})});toast('Profilbereich aktualisiert');adminView()}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(!confirm('Benutzer wirklich löschen?'))return;try{await api('/api/admin/users/'+b.dataset.del,{method:'DELETE'});adminView()}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-add]').forEach(s=>s.onchange=async()=>{if(!s.value)return;try{await api(`/api/admin/classes/${s.dataset.add}/members/${s.value}`,{method:'POST'});adminView()}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{const [c,u]=b.dataset.remove.split(':');try{await api(`/api/admin/classes/${c}/members/${u}`,{method:'DELETE'});adminView()}catch(e){toast(e.message)}});
 const ncodes=$('#newUploadCode');if(ncodes)ncodes.onclick=async()=>{try{const d=await api('/api/admin/upload-codes',{method:'POST'});try{await navigator.clipboard.writeText(d.code)}catch{};toast('Freigabecode: '+d.code);adminView()}catch(e){toast(e.message)}};document.querySelectorAll('[data-copy-code]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copyCode);toast('Code kopiert')}catch{toast('Code: '+b.dataset.copyCode)}});const tc=$('#ttClass'),td=$('#ttDay');if(tc)tc.onchange=renderTimetableEditor;if(td)td.onchange=renderTimetableEditor;
}
function bind(){setupPwaInstall();const sp=$('#saveProfile');if(sp)sp.onclick=async()=>{try{const d=await api('/api/profile',{method:'PATCH',body:JSON.stringify({name:$('#profileName').value,bio:$('#profileBio').value,avatarColor:$('#profileColor').value,avatarMode:$('#avatarMode').value,avatarEmoji:$('#avatarEmoji').value,preferences:{design:JSON.parse(localStorage.getItem('klassencloud-design')||'{}')}})});currentUser=d.user;$('#profileQuick').textContent=initials(currentUser.name);toast('Profil gespeichert');render()}catch(e){toast(e.message)}};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{applyPreset(b.dataset.preset);render()});const sd=$('#saveDesignBtn');if(sd)sd.onclick=()=>{state.accent=$('#designAccent').value;state.bg=$('#designBg').value;state.panel=$('#designPanel').value;state.radius=$('#designRadius').value;state.preset='custom';saveDesign();toast('Eigenes Design gespeichert');render()};document.querySelectorAll('#notificationBtn').forEach(b=>b.onclick=async()=>{const ok=await requestNotifications();toast(ok?'🔔 Benachrichtigungen sind aktiviert.':'Benachrichtigungen wurden nicht aktiviert.')});document.querySelectorAll('#enableNotifications').forEach(b=>b.onclick=async()=>{const ok=await requestNotifications();toast(ok?'🔔 Benachrichtigungen sind aktiviert.':'Benachrichtigungen wurden nicht aktiviert.')});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go));document.querySelectorAll('[data-class]').forEach(b=>b.onclick=async()=>{await openClass(Number(b.dataset.class));renderSidebarActive()});document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{await openPrivate(Number(b.dataset.user));renderSidebarActive()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=async()=>{await openGroup(Number(b.dataset.group));renderSidebarActive()});const ng=$('#newGroup');if(ng)ng.onclick=async()=>{const name=prompt('Name der neuen Gruppe:');if(!name?.trim())return;const users=(await api('/api/groups/users')).users;const selected=prompt('Mitglieder hinzufügen (Namen mit Komma trennen):\n\n'+users.map(u=>u.name).join('\n'));const names=(selected||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);const ids=users.filter(u=>names.includes(u.name.toLowerCase())).map(u=>u.id);try{const d=await api('/api/groups',{method:'POST',body:JSON.stringify({name:name.trim(),memberIds:ids})});selectedGroup=d.group.id;chatMode='group';chatView();toast('Gruppe erstellt')}catch(e){toast(e.message)}};const np=$('#newPrivate');if(np)np.onclick=()=>{const users=window.chatUsers||[];if(!users.length)return toast('Keine anderen aktiven Benutzer verfügbar.');const name=prompt('Name des Benutzers eingeben:\n\n'+users.map(u=>u.name).join('\n'));const u=users.find(x=>x.name.toLowerCase()===String(name||'').trim().toLowerCase());if(u){openPrivate(u.id)}else if(name)toast('Benutzer nicht gefunden.');};}
function renderSidebarActive(){}
const sidebarKey='klassencloud-sidebar-collapsed';if(localStorage.getItem(sidebarKey)==='1')document.body.classList.add('sidebar-collapsed');const sidebarToggleEl=$('#sidebarToggle');if(sidebarToggleEl)sidebarToggleEl.onclick=()=>{const collapsed=document.body.classList.toggle('sidebar-collapsed');localStorage.setItem(sidebarKey,collapsed?'1':'0')};const loginFormEl=$('#loginForm'),registerFormEl=$('#registerForm'),loginErrorEl=$('#loginError'),registerErrorEl=$('#registerError');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{setView(b.dataset.view);if(window.innerWidth<=720)$('#sidebar').classList.remove('open')});$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#profileQuick').onclick=()=>setView('profile');$('#themeBtn').onclick=()=>{applyPreset(state.theme==='dark'?'white':'current');render()};$('#logoutBtn').onclick=async()=>{await api('/api/logout',{method:'POST'});currentUser=null;showAuth()};loginFormEl.onsubmit=async e=>{e.preventDefault();loginErrorEl.textContent='';try{const f=new FormData(e.target),d=await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});currentUser=d.user;enter()}catch(x){loginErrorEl.textContent=x.message}};registerFormEl.onsubmit=async e=>{e.preventDefault();registerErrorEl.textContent='';try{const f=new FormData(e.target),d=await api('/api/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});currentUser=d.user;enter()}catch(x){registerErrorEl.textContent=x.message}};applyDesign();boot();
